// Filter workflows that have AI expressions
const items = $input.all();
const brokenWorkflows = [];

for (const item of items) {
  if (item.json && item.json.data) {
    for (const workflow of item.json.data) {
      // Check if workflow has AI expressions by looking at the workflow data
      const workflowJson = JSON.stringify(workflow);
      if (workflowJson.includes('$fromAI') || workflowJson.includes('n8n-auto-generated-fromAI-override')) {
        brokenWorkflows.push({
          id: workflow.id,
          name: workflow.name,
          hasAIExpressions: true
        });
      }
    }
  }
}

return brokenWorkflows.map(workflow => ({ json: workflow }));

// Clean the workflow by removing AI expressions and read-only properties
const workflow = $input.first().json;

// Remove read-only properties
const cleanWorkflow = {
  name: workflow.name,
  nodes: workflow.nodes,
  connections: workflow.connections,
  settings: workflow.settings,
  staticData: workflow.staticData
};

// Fix AI expressions in nodes
if (cleanWorkflow.nodes) {
  cleanWorkflow.nodes = cleanWorkflow.nodes.map(node => {
    if (node.parameters) {
      // Convert parameters to string and fix expressions
      const paramsStr = JSON.stringify(node.parameters);
      let fixedParamsStr = paramsStr;

      // Replace $fromAI expressions
      fixedParamsStr = fixedParamsStr.replace(/\$fromAI\([^)]*\)/g, '{{ $json.default_value }}');

      // Remove AI comment markers
      fixedParamsStr = fixedParamsStr.replace(/\/\*n8n-auto-generated-fromAI-override\*\/ /g, '');

      // Parse back to object
      try {
        node.parameters = JSON.parse(fixedParamsStr);
      } catch (e) {
        // If parsing fails, keep original but log
        console.log('Failed to parse fixed parameters for node:', node.name);
      }
    }
    return node;
  });
}

return [{ json: cleanWorkflow }];

// Check if import was successful and prepare response
const importResult = $input.first().json;
const originalWorkflow = $('🔍 Filter Broken Workflows').item.json;

if (importResult.id) {
  return [{
    json: {
      status: 'success',
      message: `✅ Successfully imported clean workflow: ${originalWorkflow.name}`,
      newId: importResult.id,
      originalId: originalWorkflow.id,
      workflowName: originalWorkflow.name
    }
  }];
} else {
  return [{
    json: {
      status: 'error',
      message: `❌ Failed to import workflow: ${originalWorkflow.name}`,
      error: importResult.message || importResult.error || 'Unknown error',
      workflowName: originalWorkflow.name
    }
  }];
}
